import { useEffect } from 'react';
import {
  Link,
  NavLink,
  NavigationType,
  useLocation,
  useMatch,
  useNavigate,
  useNavigationType,
} from 'react-router-dom';
import { usePane } from '@/components/layout/pane.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { SETTINGS_ROOT } from './paths.js';
import styles from './Settings.module.css';

/**
 * One page under Settings: a back control and the page's title, then its
 * sections, on the same column and spacing as the main Settings page.
 *
 * Back goes back through the history when there is some, so a page opened
 * from Today returns to Today. A page that was the first thing opened — a
 * link from a notification, an e-mail or a bookmark — has nothing behind
 * it, and back takes it up to Settings instead of doing nothing.
 */
export function SubPage({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}): React.JSX.Element {
  const navigate = useNavigate();
  const location = useLocation();
  const navigationType = useNavigationType();
  // Beside the list on an expanded window: the list is the way back, so
  // there is no back button, and the pane starts at its own top.
  const pane = usePane();

  // Arriving at a page starts at its top. Settings is short, but the page
  // it was opened from may not have been; a step back keeps where it was.
  useEffect(() => {
    if (pane === undefined && navigationType !== NavigationType.Pop) window.scrollTo(0, 0);
  }, [navigationType, pane]);

  const Root = pane === undefined ? 'main' : 'div';
  return (
    <Root className={styles.screen}>
      <header className={styles.subHead}>
        {pane === undefined && (
          <button
            type="button"
            className={styles.back}
            aria-label={t('action.back')}
            onClick={() => {
              if (location.key === 'default') void navigate(SETTINGS_ROOT, { replace: true });
              else void navigate(-1);
            }}
          >
            <Icon name="chevronLeft" size={22} weight={2} />
          </button>
        )}
        <h1 className={styles.title}>{title}</h1>
      </header>
      {children}
    </Root>
  );
}

/** A row on the main page that opens one of the pages, with what it holds at a glance. */
export function NavRow({
  to,
  icon,
  label,
  value,
  also,
}: {
  to: string;
  icon: IconName;
  label: string;
  value?: string | undefined;
  /**
   * A page reached through this one, which the list marks as this row
   * beside it on a large screen (the schedule page under Notebooks).
   */
  also?: string | undefined;
}): React.JSX.Element {
  const onAlso = useMatch(also ?? '/__never__') !== null && also !== undefined;
  // NavLink marks only its own address; on the page reached through it the
  // row is marked by hand, the same way.
  const Row = onAlso ? Link : NavLink;
  return (
    <Row
      to={to}
      className={cx(styles.row, styles.button, styles.navRow)}
      {...(onAlso ? { 'aria-current': 'page' as const } : {})}
    >
      <span className={styles.navIcon}>
        <Icon name={icon} size={18} />
      </span>
      <span className={cx(styles.label, styles.navLabel)}>{label}</span>
      {value !== undefined && value !== '' && <span className={styles.value}>{value}</span>}
      <Icon name="chevronRight" size={18} weight={2} className={styles.chevron} />
    </Row>
  );
}

/** One switch row: a label and the prototype's 44×26 toggle. */
export function SwitchRow({
  label,
  checked,
  dim = false,
  disabled = false,
  onChange,
}: {
  label: string;
  checked: boolean;
  dim?: boolean;
  /** Resting, with the reason said elsewhere on the page (offline, saving). */
  disabled?: boolean;
  onChange: (checked: boolean) => void;
}): React.JSX.Element {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      disabled={disabled}
      className={cx(styles.row, disabled && styles.rowDisabled)}
      onClick={() => {
        onChange(!checked);
      }}
    >
      <span className={cx(styles.label, styles.switchLabel, dim && styles.off)}>{label}</span>
      <span className={cx(styles.switch, checked && styles.switchOn)}>
        <span className={styles.knob} />
      </span>
    </button>
  );
}

/** A daily limit, shown as a slider so its range is visible. */
export function Slider({
  label,
  value,
  min,
  max,
  step,
  onChange,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  onChange: (value: number) => void;
}): React.JSX.Element {
  return (
    <div className={cx(styles.row, styles.rowStacked, styles.rowStatic)}>
      <span className={styles.sliderHead}>
        <span className={styles.label}>{label}</span>
        <span className={styles.sliderValue}>{value}</span>
      </span>
      <input
        type="range"
        className={styles.slider}
        aria-label={label}
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(event) => {
          onChange(Number(event.target.value));
        }}
      />
    </div>
  );
}

/** The outcome of the last action on a page, read out as it changes. */
export function StatusLine({
  status,
  failed,
}: {
  status: string | undefined;
  failed: boolean;
}): React.JSX.Element | null {
  if (status === undefined) return null;
  return (
    <p className={cx(styles.status, failed && styles.statusError)} role="status">
      {status}
    </p>
  );
}

/** A heading over a group of rows, and the rows. */
export function Section({
  title,
  id,
  children,
}: {
  title?: string | undefined;
  /** An anchor another screen may open the page at. */
  id?: string | undefined;
  children: React.ReactNode;
}): React.JSX.Element {
  return (
    <section id={id} className={styles.section}>
      {title !== undefined && <h2 className={styles.sectionTitle}>{title}</h2>}
      {children}
    </section>
  );
}
